"""AST construction and static validation for foundational jq filters."""

from __future__ import annotations

from dataclasses import dataclass

from .diagnostics import CompileError
from .lexer import Token, tokenize


@dataclass(frozen=True)
class Filter:
    kind: str
    value: object = None
    children: tuple["Filter", ...] = ()


def parse(program: str) -> Filter:
    tokens = tokenize(program)
    cursor = 0

    def expression() -> Filter:
        nonlocal cursor
        left = term()
        children = [left]
        while tokens[cursor].kind == "COMMA":
            cursor += 1
            children.append(term())
        if len(children) > 1:
            return Filter("comma", children=tuple(children))
        return left

    def term() -> Filter:
        nonlocal cursor
        token: Token = tokens[cursor]
        cursor += 1
        if token.kind == "DOT":
            return Filter("identity")
        if token.kind == "LITERAL":
            return Filter("literal", value=token.value)
        if token.kind == "IDENT":
            if token.value == "error":
                return Filter("error")
            raise CompileError(f"unknown filter at position {token.position}")
        raise CompileError(f"expected filter at position {token.position}")

    if tokens[0].kind == "EOF":
        raise CompileError("empty filter")
    result = expression()
    if tokens[cursor].kind != "EOF":
        raise CompileError(f"unexpected token at position {tokens[cursor].position}")
    return result
